<script setup lang="ts">
import {ref,watch,onBeforeUnmount,computed} from 'vue';
import {Button,Input,Switch,Dialog,useHostContext} from '@openclaw-plugins/control-ui-kit';
import AuditView from './AuditView.vue';
import type {AuditPage} from './audit-model';
type Snapshot={projectId:string;revision:string;config:{enabled:boolean;maxSize:number};occupied:number;pendingCommit?:boolean;slots:{id:string;status:string;path?:string;owner?:string;branch?:string;target?:string;error?:string;dependencies?:{repository:string;installedAt?:string}[]}[]};
const props=defineProps<{projectId:string;invoke:<T>(action:string,payload:Record<string,unknown>)=>Promise<T>;canWrite:()=>boolean;safe?:(value:unknown)=>string}>();
const context=useHostContext(),open=ref(false),audit=ref(false),data=ref<Snapshot>(),busy=ref(false),saving=ref(false),message=ref(''),enabled=ref(false),capacity=ref<string|number>(3);
const writable=computed(()=>context.value.host.connection.canWrite&&props.canWrite());
const safe=(value:unknown)=>props.safe?.(value)??String(value??'');
const labels:Record<string,string>={idle:'空闲',preparing:'初始化中',ready:'待执行',running:'执行中',held:'等待补充',checking:'检查释放条件',blocked:'异常保留'};
let alive=true,epoch=0;
function assign(next:Snapshot){data.value=next;enabled.value=next.config.enabled;capacity.value=next.config.maxSize;}
async function load(){audit.value=false;const token=++epoch;busy.value=true;try{const next=await props.invoke<Snapshot>('workspacePool',{projectId:props.projectId});if(!alive||token!==epoch||!open.value)return;if(!next?.config||!Array.isArray(next.slots))throw Error('当前宿主暂不支持工作区管理');assign(next);message.value='';}catch(e){if(alive&&token===epoch)message.value=safe(e instanceof Error?e.message:e);}finally{if(alive&&token===epoch)busy.value=false;}}
async function save(){if(busy.value||!writable.value||!data.value)return;const maxSize=Number(capacity.value);if(!Number.isInteger(maxSize)||maxSize<1||maxSize>20){message.value='容量必须为 1–20 的整数';return;}const token=++epoch;busy.value=true;saving.value=true;try{const next=await props.invoke<Snapshot>('workspacePoolSave',{projectId:props.projectId,revision:data.value.revision,enabled:enabled.value,maxSize});if(!alive||token!==epoch||!open.value)return;assign(next);message.value='池配置已保存。';}catch(e){if(alive&&token===epoch)message.value=safe(e instanceof Error?e.message:e);}finally{if(alive&&token===epoch){busy.value=false;saving.value=false;}}}
function showAudit(){if(saving.value)return;epoch++;busy.value=false;audit.value=true;}
const auditInvoke=(action:string,payload:Record<string,unknown>)=>props.invoke<AuditPage>(action,payload);
watch(open,value=>{epoch++;data.value=undefined;busy.value=false;saving.value=false;message.value='';if(value)void load();else audit.value=false;});
watch(()=>props.projectId,()=>{open.value=false;},{flush:'sync'});
onBeforeUnmount(()=>{alive=false;epoch++;});
</script>
<template><span class="ar-workspace-pool"><Button variant="outline" aria-haspopup="dialog" @click="open=true">工作区配置</Button><Dialog v-model:open="open" title="代码工作区池" content-class="ocp:max-w-4xl"><div class="ar-sync-dialog-header"><Button variant="outline" :disabled="saving" @click="showAudit">修改日志</Button></div><AuditView v-if="audit" :invoke="auditInvoke" :safe="safe" feature="workspace" :target-id="projectId" :on-close="load"/><div v-else class="ar-sync-dialog-body ar-workspace-content"><p>projects 用于常规只读任务；workspace 用于已授权的代码修改与 PR。池满时原任务等待释放。</p><Button variant="outline" :disabled="busy" @click="load">刷新工作区</Button><p v-if="message" role="status">{{message}}</p><p v-if="busy&&!data">正在读取…</p><template v-if="data"><p>保存会修改 projects.json；请在维护窗口调整，随后按仓库流程提交同步。不会自动 commit、push 或重启。</p><form @submit.prevent="save"><label>启用独立工作区 <Switch v-model="enabled" :disabled="busy||!writable" aria-label="启用独立工作区"/></label><label>最大工作区数量 <Input v-model="capacity" type="number" min="1" max="20" step="1" required :disabled="busy||!writable"/></label><Button type="submit" :disabled="busy||!writable">保存池配置</Button></form><p>已分配 {{data.slots.length}} 个，占用或保留 {{data.occupied}} 个。缩容或停用不会中断已分配任务，也不会删除目录。</p><p v-if="!writable">当前连接仅有读取权限。</p><p v-if="data.pendingCommit">projects.json 有待提交的变化；提交同步前，新任务准备与自动同步可能暂停，已分配任务不强制停止。</p><p v-if="!data.slots.length">尚未创建工作区；首次代码任务到来时按需创建。</p><details v-for="slot in data.slots" :key="slot.id"><summary>{{safe(slot.id+' · '+(labels[slot.status]??slot.status))}}</summary><template v-for="[key,value] in [['目录',slot.path],['任务',slot.owner],['分支',slot.branch],['目标仓库',slot.target],['保留原因',slot.error]]" :key="key"><p v-if="value">{{safe(key+'：'+value)}}</p></template><p v-for="d in slot.dependencies??[]" :key="d.repository">{{safe('依赖 '+d.repository+' · '+(d.installedAt?new Date(d.installedAt).toLocaleString():'未记录'))}}</p><p v-if="slot.status==='blocked'">请先人工核验未提交代码、远端提交与进程状态；此处不执行强制释放或清理。</p></details></template></div></Dialog></span></template>
